WITH flattened_attrs AS (SELECT id, host, log_ts, payload_json, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, SHIFTRIGHT(status_code, 2) AS status_code_high, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs) SELECT id, host, retry_count, status_code_high, LEAD(status_code_high, 1) OVER (ORDER BY status_code_high, id) AS next_status_code_high, CUME_DIST() OVER (PARTITION BY host ORDER BY retry_count NULLS LAST) AS retry_count_cume_dist FROM flattened_attrs WHERE status_code_high BETWEEN 1 AND 2
